-- =====================================================================
--  FINANCIERA - Grillas de valores (las de Reggio: general, Nación,
--  Matanza, Si o Si, Neuquén y DG)
--  Correr desde CMD (tiene DELIMITER), se puede correr más de una vez:
--    mysql -u root -p --default-character-set=utf8mb4 financiera < financiera_grillas.sql
--
--  Una grilla dice el valor de la cuota (capital + interés + IVA) según el
--  monto prestado y la cantidad de cuotas. Cada tipo de asociado puede
--  tener una (tipos_asociado.id_grilla). Al simular y al liquidar:
--    - si el tipo tiene grilla y el monto y el plazo están en ella (la
--      celda exacta o entre dos montos de la grilla, interpolando), todas
--      las cuotas son la de la grilla, IVA incluido (como Reggio): la TNA
--      sale de esa cuota (fn_tna_para_cuota) y el cuadro de
--      sp_cuadro_cuota_fija reparte cada cuota en interés, IVA y capital;
--    - si no, la tasa vigente de la solapa Tasas, como siempre.
--  El resto (cuotas, IVA, punitorios, facturación) sale de esa TNA.
--  Lo que dice cada grilla es deducción de las pantallas de Reggio: ver
--  preguntas_cliente.md. La asignación a los tipos es provisoria.
-- =====================================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS grillas (
    id_grilla    INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre       VARCHAR(60)  NOT NULL,
    descripcion  VARCHAR(200) NULL,
    origen       VARCHAR(20)  NULL COMMENT 'REGGIO: importada del sistema viejo',
    activo       TINYINT(1)   NOT NULL DEFAULT 1,
    creado_el    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_grilla),
    UNIQUE KEY uq_grillas_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Grillas de valores: la cuota según monto y cantidad de cuotas';

CREATE TABLE IF NOT EXISTS grillas_celdas (
    id_grilla      INT UNSIGNED      NOT NULL,
    monto          DECIMAL(15,2)     NOT NULL COMMENT 'Monto prestado',
    plazo          SMALLINT UNSIGNED NOT NULL COMMENT 'Cantidad de cuotas',
    valor_cuota    DECIMAL(15,2)     NOT NULL COMMENT 'Cuota (capital + interés + IVA)',
    modificado_por INT UNSIGNED      NULL,
    modificado_el  DATETIME          NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id_grilla, plazo, monto),
    CONSTRAINT fk_gc_grilla FOREIGN KEY (id_grilla) REFERENCES grillas (id_grilla)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
  COMMENT='Celdas de las grillas de valores';

DELIMITER $$
DROP PROCEDURE IF EXISTS tmp_grillas $$
CREATE PROCEDURE tmp_grillas()
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                    WHERE table_schema = DATABASE() AND table_name = 'tipos_asociado' AND column_name = 'id_grilla') THEN
        ALTER TABLE tipos_asociado
            ADD COLUMN id_grilla INT UNSIGNED NULL COMMENT 'Grilla de valores: la cuota sale de ahí',
            ADD CONSTRAINT fk_ta_grilla FOREIGN KEY (id_grilla) REFERENCES grillas (id_grilla);
    END IF;
END $$
CALL tmp_grillas() $$
DROP PROCEDURE IF EXISTS tmp_grillas $$

-- La cuota de la grilla del tipo de asociado para un monto y un plazo: la
-- celda exacta o, entre dos montos de la grilla, la interpolación lineal.
-- NULL si el tipo no tiene grilla o el monto/plazo queda afuera.
DROP FUNCTION IF EXISTS fn_grilla_cuota $$
CREATE FUNCTION fn_grilla_cuota(p_id_tipo_asociado INT UNSIGNED, p_monto DECIMAL(15,2), p_plazo SMALLINT)
RETURNS DECIMAL(15,2)
READS SQL DATA
BEGIN
    DECLARE v_grilla INT UNSIGNED;
    DECLARE v_exacta DECIMAL(15,2);
    DECLARE v_m1, v_m2, v_c1, v_c2 DECIMAL(15,2);

    SELECT t.id_grilla INTO v_grilla
      FROM tipos_asociado t JOIN grillas g ON g.id_grilla = t.id_grilla AND g.activo = 1
     WHERE t.id_tipo_asociado = p_id_tipo_asociado;
    IF v_grilla IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT valor_cuota INTO v_exacta FROM grillas_celdas
     WHERE id_grilla = v_grilla AND plazo = p_plazo AND monto = p_monto;
    IF v_exacta IS NOT NULL THEN
        RETURN v_exacta;
    END IF;

    SELECT monto, valor_cuota INTO v_m1, v_c1 FROM grillas_celdas
     WHERE id_grilla = v_grilla AND plazo = p_plazo AND monto < p_monto ORDER BY monto DESC LIMIT 1;
    SELECT monto, valor_cuota INTO v_m2, v_c2 FROM grillas_celdas
     WHERE id_grilla = v_grilla AND plazo = p_plazo AND monto > p_monto ORDER BY monto LIMIT 1;
    IF v_m1 IS NULL OR v_m2 IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN ROUND(v_c1 + (v_c2 - v_c1) * (p_monto - v_m1) / (v_m2 - v_m1), 2);
END $$

-- La TNA de un préstamo de cuota fija con IVA incluido (la de la grilla):
-- con j = tasa mensual x (1 + IVA), p_cuota = capital x j / (1 - (1+j)^-n).
-- Devuelve la TNA sin IVA (12 x j / (1 + IVA)). NULL si la cuota no
-- alcanza a cubrir el capital. Bisección: la cuota crece con la tasa.
DROP FUNCTION IF EXISTS fn_tna_para_cuota $$
CREATE FUNCTION fn_tna_para_cuota(p_capital DECIMAL(15,2), p_plazo SMALLINT, p_alic DECIMAL(6,4), p_cuota DECIMAL(15,2))
RETURNS DECIMAL(9,6)
DETERMINISTIC
BEGIN
    DECLARE v_lo, v_hi, v_mid, v_c DOUBLE;
    DECLARE n INT DEFAULT 0;

    IF p_capital IS NULL OR p_capital <= 0 OR p_plazo < 1 OR p_cuota IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_cuota < ROUND(p_capital / p_plazo, 2) THEN
        RETURN NULL;
    END IF;
    SET v_lo = 0, v_hi = 6;
    WHILE n < 100 DO
        SET v_mid = (v_lo + v_hi) / 2;
        SET v_c = p_capital * v_mid / (1 - POW(1 + v_mid, -p_plazo));
        IF v_c > p_cuota THEN
            SET v_hi = v_mid;
        ELSE
            SET v_lo = v_mid;
        END IF;
        SET n = n + 1;
    END WHILE;
    IF v_lo * 12 / (1 + p_alic) > 999 THEN
        RETURN NULL;
    END IF;
    RETURN ROUND(v_lo * 12 / (1 + p_alic), 6);
END $$

-- Cuadro de cuota fija con IVA incluido (préstamos de grilla, como Reggio):
-- todas las cuotas son p_cuota; el interés es el saldo x TNA/12, su IVA
-- aparte, y el capital lo que queda. La última cancela el saldo. Deja
-- tmp_cuadro igual que sp_cuadro_frances.
DROP PROCEDURE IF EXISTS sp_cuadro_cuota_fija $$
CREATE PROCEDURE sp_cuadro_cuota_fija(
    IN p_capital    DECIMAL(15,2),
    IN p_plazo      SMALLINT,
    IN p_cuota      DECIMAL(15,2),
    IN p_tna        DECIMAL(9,6),
    IN p_alic_iva   DECIMAL(6,4),
    IN p_primer_vto DATE
)
BEGIN
    DECLARE v_i       DOUBLE;
    DECLARE v_saldo   DECIMAL(15,2);
    DECLARE v_interes DECIMAL(15,2);
    DECLARE v_capital DECIMAL(15,2);
    DECLARE v_iva     DECIMAL(15,2);
    DECLARE n         SMALLINT DEFAULT 1;

    DROP TEMPORARY TABLE IF EXISTS tmp_cuadro;
    CREATE TEMPORARY TABLE tmp_cuadro (
        nro_cuota     SMALLINT UNSIGNED NOT NULL PRIMARY KEY,
        vencimiento   DATE          NOT NULL,
        capital       DECIMAL(15,2) NOT NULL,
        interes       DECIMAL(15,2) NOT NULL,
        iva_interes   DECIMAL(15,2) NOT NULL,
        importe       DECIMAL(15,2) NOT NULL,
        saldo_capital DECIMAL(15,2) NOT NULL
    ) ENGINE=MEMORY;

    SET v_i = p_tna / 12;
    SET v_saldo = p_capital;
    WHILE n <= p_plazo DO
        SET v_interes = ROUND(v_saldo * v_i, 2);
        SET v_iva     = ROUND(v_interes * p_alic_iva, 2);
        IF n = p_plazo THEN
            SET v_capital = v_saldo;
        ELSE
            SET v_capital = LEAST(v_saldo, GREATEST(0, p_cuota - v_interes - v_iva));
        END IF;
        SET v_saldo = v_saldo - v_capital;
        INSERT INTO tmp_cuadro
        VALUES (n, DATE_ADD(p_primer_vto, INTERVAL (n - 1) MONTH),
                v_capital, v_interes, v_iva, v_capital + v_interes + v_iva, v_saldo);
        SET n = n + 1;
    END WHILE;
END $$

-- ---------------------------------------------------------------------
-- sp_simular_prestamo: la de financiera_gastos.sql, con la grilla.
-- Si el tipo tiene grilla y el monto y el plazo están en ella, la TNA sale
-- de la cuota de la grilla; si no, de la tasa vigente.
-- ---------------------------------------------------------------------
DROP PROCEDURE IF EXISTS sp_simular_prestamo $$
CREATE PROCEDURE sp_simular_prestamo(
    IN p_id_tipo_asociado INT UNSIGNED,
    IN p_capital     DECIMAL(15,2),
    IN p_plazo       SMALLINT,
    IN p_fecha       DATE,
    IN p_primer_vto  DATE
)
BEGIN
    DECLARE v_id_tasa  INT UNSIGNED;
    DECLARE v_tna      DECIMAL(9,6);
    DECLARE v_iva      DECIMAL(6,4);
    DECLARE v_pmin, v_pmax SMALLINT;
    DECLARE v_mmin, v_mmax DECIMAL(15,2);
    DECLARE v_activo   TINYINT;
    DECLARE v_desc, v_fin DECIMAL(15,2);
    DECLARE v_cuota, v_int, v_ivat, v_total DECIMAL(15,2);
    DECLARE v_grilla   DECIMAL(15,2);
    DECLARE v_con_grilla TINYINT;

    SET p_fecha      = COALESCE(p_fecha, CURDATE());
    SET p_primer_vto = COALESCE(p_primer_vto, DATE_ADD(p_fecha, INTERVAL 1 MONTH));

    SELECT alicuota_iva, plazo_min, plazo_max, monto_min, monto_max, activo, id_grilla IS NOT NULL
      INTO v_iva, v_pmin, v_pmax, v_mmin, v_mmax, v_activo, v_con_grilla
      FROM tipos_asociado WHERE id_tipo_asociado = p_id_tipo_asociado;

    IF v_activo IS NULL OR v_activo = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Tipo de asociado inexistente o inactivo';
    END IF;
    IF p_plazo NOT BETWEEN v_pmin AND v_pmax THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Plazo fuera del rango del tipo de asociado';
    END IF;
    IF p_capital NOT BETWEEN v_mmin AND v_mmax THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Monto fuera del rango del tipo de asociado';
    END IF;

    CALL sp_gastos_calcular(p_id_tipo_asociado, p_capital);
    SELECT COALESCE(SUM(IF(forma_cobro = 'DESCUENTO', total, 0)), 0),
           COALESCE(SUM(IF(forma_cobro = 'FINANCIADO', total, 0)), 0)
      INTO v_desc, v_fin
      FROM tmp_gastos;
    IF v_desc >= p_capital THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Los gastos que se descuentan igualan o superan el monto pedido';
    END IF;

    SET v_id_tasa = fn_tasa_vigente(p_id_tipo_asociado, p_plazo, p_capital, p_fecha);
    SET v_grilla  = fn_grilla_cuota(p_id_tipo_asociado, p_capital, p_plazo);
    IF v_grilla IS NOT NULL THEN
        SET v_tna = fn_tna_para_cuota(p_capital + v_fin, p_plazo, v_iva, v_grilla);
        IF v_tna IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cuota de la grilla no alcanza a cubrir el capital: revisá la grilla del tipo';
        END IF;
    ELSEIF v_id_tasa IS NULL THEN
        IF v_con_grilla THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ese monto y plazo no están en la grilla del tipo ni hay tasa vigente';
        END IF;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay tasa vigente para ese plazo y monto';
    ELSE
        SELECT tna INTO v_tna FROM tasas_vigencia WHERE id_tasa = v_id_tasa;
    END IF;

    IF v_grilla IS NOT NULL THEN
        CALL sp_cuadro_cuota_fija(p_capital + v_fin, p_plazo, v_grilla, v_tna, v_iva, p_primer_vto);
    ELSE
        CALL sp_cuadro_frances(p_capital + v_fin, p_plazo, v_tna, v_iva, p_primer_vto);
    END IF;

    SELECT SUM(IF(nro_cuota = 1, importe, 0)), SUM(interes), SUM(iva_interes), SUM(importe)
      INTO v_cuota, v_int, v_ivat, v_total
      FROM tmp_cuadro;

    SELECT p_capital                                   AS capital,
           p_plazo                                     AS plazo,
           v_tna                                       AS tna,
           ROUND(v_tna / 12, 6)                        AS tem,
           ROUND(POW(1 + v_tna / 12, 12) - 1, 6)       AS tea,
           v_desc                                      AS gastos_otorg,
           v_fin                                       AS gastos_financiados,
           p_capital + v_fin                           AS capital_financiado,
           p_capital - v_desc                          AS neto_desembolso,
           v_cuota                                     AS valor_cuota,
           v_int                                       AS total_intereses,
           v_ivat                                      AS total_iva,
           v_total                                     AS total_a_pagar,
           v_grilla                                    AS cuota_grilla;

    SELECT * FROM tmp_cuadro ORDER BY nro_cuota;

    SELECT id_concepto_gasto, codigo, nombre, tipo_calculo, valor, forma_cobro, base, importe, alicuota_iva, iva, total
      FROM tmp_gastos ORDER BY orden, nombre;
END $$

-- ---------------------------------------------------------------------
-- sp_liquidar_prestamo: la de financiera_telemarketing_comisiones.sql /
-- financiera_gastos.sql, con la grilla (como sp_simular_prestamo). La
-- punitoria de un préstamo de grilla sin tasa: TNA x PUNITORIO_PCT_TNA.
-- ---------------------------------------------------------------------
DROP PROCEDURE IF EXISTS sp_liquidar_prestamo $$
CREATE PROCEDURE sp_liquidar_prestamo(
    IN  p_nro_prestamo  VARCHAR(20),
    IN  p_id_cliente    INT UNSIGNED,
    IN  p_id_tipo_asociado INT UNSIGNED,
    IN  p_id_vendedor   INT UNSIGNED,
    IN  p_capital       DECIMAL(15,2),
    IN  p_plazo         SMALLINT,
    IN  p_fecha         DATE,
    IN  p_primer_vto    DATE,
    IN  p_comision_pct  DECIMAL(9,6),
    IN  p_telemarketing TINYINT,
    IN  p_id_usuario    INT UNSIGNED,
    OUT p_id_prestamo   INT UNSIGNED
)
BEGIN
    DECLARE v_id_tasa   INT UNSIGNED;
    DECLARE v_tna       DECIMAL(9,6);
    DECLARE v_punit     DECIMAL(9,6);
    DECLARE v_iva       DECIMAL(6,4);
    DECLARE v_desc, v_fin DECIMAL(15,2);
    DECLARE v_pmin, v_pmax SMALLINT;
    DECLARE v_mmin, v_mmax DECIMAL(15,2);
    DECLARE v_activo    TINYINT;
    DECLARE v_estado_cli VARCHAR(20);
    DECLARE v_id_regla  INT UNSIGNED DEFAULT NULL;
    DECLARE v_com_pct   DECIMAL(9,6) DEFAULT NULL;
    DECLARE v_com_base  DECIMAL(15,2);
    DECLARE v_com_monto DECIMAL(15,2) DEFAULT NULL;
    DECLARE v_base_tipo VARCHAR(20);
    DECLARE v_cuota, v_int, v_ivat DECIMAL(15,2);
    DECLARE v_grilla    DECIMAL(15,2);
    DECLARE v_con_grilla TINYINT;
    DECLARE v_pct_pun   DECIMAL(9,6);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET p_fecha      = COALESCE(p_fecha, CURDATE());
    SET p_telemarketing = COALESCE(p_telemarketing, 0);
    SET p_primer_vto = COALESCE(p_primer_vto, DATE_ADD(p_fecha, INTERVAL 1 MONTH));

    SELECT estado INTO v_estado_cli FROM clientes WHERE id_cliente = p_id_cliente;
    IF v_estado_cli IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cliente inexistente';
    END IF;
    IF v_estado_cli <> 'ACTIVO' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El cliente no está activo';
    END IF;

    SELECT alicuota_iva, plazo_min, plazo_max, monto_min, monto_max, activo, id_grilla IS NOT NULL
      INTO v_iva, v_pmin, v_pmax, v_mmin, v_mmax, v_activo, v_con_grilla
      FROM tipos_asociado WHERE id_tipo_asociado = p_id_tipo_asociado;

    IF v_activo IS NULL OR v_activo = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Tipo de asociado inexistente o inactivo';
    END IF;
    IF p_plazo NOT BETWEEN v_pmin AND v_pmax THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Plazo fuera del rango del tipo de asociado';
    END IF;
    IF p_capital NOT BETWEEN v_mmin AND v_mmax THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Monto fuera del rango del tipo de asociado';
    END IF;
    IF p_comision_pct IS NOT NULL AND (p_comision_pct < 0 OR p_comision_pct > 1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El % de comisión manual debe estar entre 0 y 1';
    END IF;

    CALL sp_gastos_calcular(p_id_tipo_asociado, p_capital);
    SELECT COALESCE(SUM(IF(forma_cobro = 'DESCUENTO', total, 0)), 0),
           COALESCE(SUM(IF(forma_cobro = 'FINANCIADO', total, 0)), 0)
      INTO v_desc, v_fin
      FROM tmp_gastos;
    IF v_desc >= p_capital THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Los gastos que se descuentan igualan o superan el monto pedido';
    END IF;

    SET v_pct_pun = COALESCE((SELECT CAST(valor AS DECIMAL(9,6)) FROM parametros WHERE clave = 'PUNITORIO_PCT_TNA'), 0.5);
    SET v_id_tasa = fn_tasa_vigente(p_id_tipo_asociado, p_plazo, p_capital, p_fecha);
    SET v_grilla  = fn_grilla_cuota(p_id_tipo_asociado, p_capital, p_plazo);
    IF v_grilla IS NOT NULL THEN
        SET v_tna = fn_tna_para_cuota(p_capital + v_fin, p_plazo, v_iva, v_grilla);
        IF v_tna IS NULL THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cuota de la grilla no alcanza a cubrir el capital: revisá la grilla del tipo';
        END IF;
        SET v_punit = ROUND(v_tna * v_pct_pun, 6);
        IF v_id_tasa IS NOT NULL THEN
            SELECT COALESCE(tasa_punitoria, v_punit) INTO v_punit FROM tasas_vigencia WHERE id_tasa = v_id_tasa;
        END IF;
    ELSEIF v_id_tasa IS NULL THEN
        IF v_con_grilla THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ese monto y plazo no están en la grilla del tipo ni hay tasa vigente';
        END IF;
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No hay tasa vigente para ese plazo y monto';
    ELSE
        SELECT t.tna, COALESCE(t.tasa_punitoria, ROUND(t.tna * v_pct_pun, 6))
          INTO v_tna, v_punit
          FROM tasas_vigencia t WHERE t.id_tasa = v_id_tasa;
    END IF;

    IF v_grilla IS NOT NULL THEN
        CALL sp_cuadro_cuota_fija(p_capital + v_fin, p_plazo, v_grilla, v_tna, v_iva, p_primer_vto);
    ELSE
        CALL sp_cuadro_frances(p_capital + v_fin, p_plazo, v_tna, v_iva, p_primer_vto);
    END IF;

    SELECT SUM(IF(nro_cuota = 1, importe, 0)), SUM(interes), SUM(iva_interes)
      INTO v_cuota, v_int, v_ivat
      FROM tmp_cuadro;

    IF p_id_vendedor IS NOT NULL THEN
        IF p_comision_pct IS NOT NULL THEN
            SET v_com_pct   = p_comision_pct;
            SET v_base_tipo = 'CAPITAL';
        ELSE
            SET v_id_regla = fn_comision_regla(p_id_vendedor, p_id_tipo_asociado, p_plazo, p_capital, p_fecha, p_telemarketing);
            IF v_id_regla IS NOT NULL THEN
                SELECT IF(p_telemarketing = 1,
                          COALESCE(r.porcentaje_tm, ROUND(r.porcentaje * COALESCE(t.pct_telemarketing, 1), 6)),
                          r.porcentaje), r.base_calculo
                  INTO v_com_pct, v_base_tipo
                  FROM comision_reglas r
                  LEFT JOIN tipos_asociado t ON t.id_tipo_asociado = r.id_tipo_asociado
                 WHERE r.id_regla = v_id_regla;
            END IF;
        END IF;

        IF v_com_pct IS NOT NULL THEN
            SET v_com_base  = IF(v_base_tipo = 'NETO_DESEMBOLSO', p_capital - v_desc, p_capital);
            SET v_com_monto = ROUND(v_com_base * v_com_pct, 2);
        END IF;
    END IF;

    START TRANSACTION;

    INSERT INTO prestamos (
        nro_prestamo, id_cliente, id_tipo_asociado, id_vendedor, id_tasa,
        fecha_liquidacion, fecha_primer_vto, capital, plazo, tna, alicuota_iva,
        tasa_punitoria, gastos_otorg, gastos_financiados, neto_desembolso, id_cuenta_fondos, medio_desembolso, referencia_desembolso,
        valor_cuota, total_intereses, total_iva,
        telemarketing, id_comision_regla, comision_pct, comision_monto, creado_por)
    VALUES (p_nro_prestamo, p_id_cliente, p_id_tipo_asociado, p_id_vendedor, v_id_tasa,
            p_fecha, p_primer_vto, p_capital, p_plazo, v_tna, v_iva,
            v_punit, v_desc, v_fin, p_capital - v_desc, NULL, NULL, NULL,
            v_cuota, v_int, v_ivat,
            p_telemarketing, v_id_regla, v_com_pct, v_com_monto, p_id_usuario);

    SET p_id_prestamo = LAST_INSERT_ID();

    INSERT INTO cuotas (id_prestamo, nro_cuota, vencimiento, capital, interes,
                        iva_interes, importe, saldo_capital)
    SELECT p_id_prestamo, nro_cuota, vencimiento, capital, interes,
           iva_interes, importe, saldo_capital
      FROM tmp_cuadro;

    INSERT INTO prestamos_gastos (id_prestamo, id_concepto_gasto, nombre, tipo_calculo, valor, forma_cobro,
                                  base, importe, alicuota_iva, iva, total)
    SELECT p_id_prestamo, id_concepto_gasto, nombre, tipo_calculo, valor, forma_cobro,
           base, importe, alicuota_iva, iva, total
      FROM tmp_gastos ORDER BY orden, nombre;

    INSERT INTO movimientos (id_prestamo, fecha, tipo, importe, referencia, creado_por)
    VALUES (p_id_prestamo, p_fecha, 'DESEMBOLSO', p_capital, p_nro_prestamo, p_id_usuario);

    IF v_desc > 0 THEN
        INSERT INTO movimientos (id_prestamo, fecha, tipo, importe, referencia, creado_por)
        VALUES (p_id_prestamo, p_fecha, 'GASTO_OTORG', v_desc, 'Descontado del desembolso', p_id_usuario);
    END IF;
    IF v_fin > 0 THEN
        INSERT INTO movimientos (id_prestamo, fecha, tipo, importe, referencia, creado_por)
        VALUES (p_id_prestamo, p_fecha, 'GASTO_FINANC', v_fin, 'Financiado en las cuotas', p_id_usuario);
    END IF;

    IF v_com_monto IS NOT NULL THEN
        INSERT INTO comisiones_devengadas (id_vendedor, id_prestamo, id_regla, fecha,
                                           concepto, base, porcentaje, importe)
        VALUES (p_id_vendedor, p_id_prestamo, v_id_regla, p_fecha,
                'ALTA', v_com_base, v_com_pct, v_com_monto);
    END IF;

    CALL sp_op_desde_prestamo(p_id_prestamo, p_id_usuario);

    COMMIT;
END $$

DELIMITER ;

