-- Asignación PROVISORIA por nombre (a confirmar con el cliente: preguntas_cliente.md).
-- Staff y juicios quedan sin grilla: no salen de ninguna grilla de Reggio.
UPDATE tipos_asociado t JOIN grillas g ON g.nombre = 'REGGIO NACION'
   SET t.id_grilla = g.id_grilla
 WHERE t.id_grilla IS NULL AND (t.nombre LIKE 'NACION%' OR t.nombre LIKE 'COFINCRED NACION%')
   AND t.nombre NOT LIKE '%STAFF%' AND t.nombre NOT LIKE '% DG' AND t.nombre NOT LIKE '%SI O SI%' AND t.nombre NOT LIKE '%JUICIO%';
UPDATE tipos_asociado t JOIN grillas g ON g.nombre = 'REGGIO DG'
   SET t.id_grilla = g.id_grilla
 WHERE t.id_grilla IS NULL AND t.nombre LIKE '% DG' AND t.nombre NOT LIKE '%STAFF%' AND t.nombre NOT LIKE '%JUICIO%';
UPDATE tipos_asociado t JOIN grillas g ON g.nombre = 'REGGIO SI O SI'
   SET t.id_grilla = g.id_grilla
 WHERE t.id_grilla IS NULL AND t.nombre LIKE '%SI O SI%';
UPDATE tipos_asociado t JOIN grillas g ON g.nombre = 'REGGIO NEUQUEN'
   SET t.id_grilla = g.id_grilla
 WHERE t.id_grilla IS NULL AND t.nombre LIKE 'NEUQUEN%' AND t.nombre NOT LIKE '%JUICIO%';
UPDATE tipos_asociado t JOIN grillas g ON g.nombre = 'REGGIO MATANZA'
   SET t.id_grilla = g.id_grilla
 WHERE t.id_grilla IS NULL AND t.nombre LIKE '%MATANZA%';

